CREATE TABLE ship_security_access_point(access_point_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,ship_id bigint NOT NULL,campaign_id bigint NOT NULL,access_security_code text NOT NULL REFERENCES rule_ship_access_security(access_security_code),access_point_name text NOT NULL CHECK(btrim(access_point_name)<>''),boundary_kind text NOT NULL CHECK(boundary_kind IN('external','internal')),access_state text NOT NULL DEFAULT 'locked' CHECK(access_state IN('locked','unlocked','disabled')),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),UNIQUE(ship_id,access_point_name));
CREATE TABLE ship_security_override_receipt(security_override_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,access_point_id bigint NOT NULL REFERENCES ship_security_access_point(access_point_id),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),access_state_before text NOT NULL,access_state_after text NOT NULL,access_version_before bigint NOT NULL,access_version_after bigint NOT NULL CHECK(access_version_after=access_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(access_state_before='locked'),CHECK(access_state_after IN('locked','unlocked')));
CREATE FUNCTION ship_finalize_security_override() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE point ship_security_access_point%ROWTYPE;profile rule_ship_access_security%ROWTYPE;task cmd_actor_task_receipt%ROWTYPE;actor_campaign bigint;expected_difficulty bigint;BEGIN SELECT * INTO STRICT point FROM ship_security_access_point WHERE access_point_id=NEW.access_point_id FOR UPDATE;SELECT * INTO STRICT profile FROM rule_ship_access_security WHERE access_security_code=point.access_security_code;SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;SELECT campaign_id INTO STRICT actor_campaign FROM actor_actor WHERE actor_id=task.actor_id;expected_difficulty:=CASE point.boundary_kind WHEN 'external' THEN profile.external_difficulty_rule_id ELSE profile.internal_difficulty_rule_id END;
 IF point.access_state<>'locked' OR point.campaign_id<>actor_campaign OR task.skill_rule_id<>profile.override_skill_rule_id OR task.difficulty_rule_id<>expected_difficulty OR NEW.access_state_before<>point.access_state OR NEW.access_version_before<>point.concurrency_version OR NEW.access_state_after<>(CASE WHEN task.succeeded THEN 'unlocked' ELSE 'locked' END) THEN RAISE EXCEPTION 'Security override must match ship access state and the published skill, difficulty, result, and version' USING ERRCODE='23514';END IF;
 UPDATE ship_security_access_point SET access_state=NEW.access_state_after,concurrency_version=NEW.access_version_after WHERE access_point_id=point.access_point_id;RETURN NEW;END $$;
CREATE TRIGGER ship_security_override_final BEFORE INSERT ON ship_security_override_receipt FOR EACH ROW EXECUTE FUNCTION ship_finalize_security_override();
CREATE FUNCTION ship_reject_security_override_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ship security override receipts are immutable';END $$;CREATE TRIGGER ship_security_override_immutable BEFORE UPDATE OR DELETE ON ship_security_override_receipt FOR EACH ROW EXECUTE FUNCTION ship_reject_security_override_mutation();
CREATE FUNCTION ship_guard_security_access_state() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Ship security access state changes require an immutable override receipt' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER ship_security_access_guard BEFORE UPDATE OR DELETE ON ship_security_access_point FOR EACH ROW EXECUTE FUNCTION ship_guard_security_access_state();
